from scipy.optimize import least_squares
def basis(w):
    return np.column_stack([np.cos(w*t),np.sin(w*t),np.ones_like(t),x,v,x**2,x**3,v*np.abs(v),v**2,v**3,x*v,np.sin(x),np.cos(x)])
def f(p):
    X=basis(p[0]); c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]; return X@c-dv_dt
best=None
for w0 in np.linspace(0.3,0.5,21):
    s=least_squares(lambda p:f(p),[w0])
    rr=np.mean(s.fun**2)/np.var(dv_dt)
    if best is None or rr<best[0]: best=(rr,s.x[0])
print(best)
X=basis(best[1]); c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
print(np.round(c,4))

